WITH ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY country, city ORDER BY rating DESC NULLS LAST, id) AS row_num FROM suppliers) ranked WHERE row_num = 1) SELECT CASE WHEN rating >= 4.3 THEN 'LARGE' ELSE 'SMALL' END AS rating_tier, APPROX_PERCENTILE(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles, COUNT(*) AS cnt, COUNT(*) FILTER (WHERE country = 'SG') AS sg_rows, PERCENTILE_APPROX(rating, ARRAY(0.25, 0.5, 0.75)) AS rating_quartiles_2, SORT_ARRAY(COLLECT_SET(country)) AS country_list, ROUND(SUM(rating) / NULLIF(COUNT(CASE WHEN city = 'New York' THEN 1 END), 0), 2) AS rating_per_new_york FROM ranked GROUP BY 1 ORDER BY cnt DESC NULLS FIRST
